"""Apply the bounded, review-first linguistic pass for HALO."""
import copy
import json
from pathlib import Path

ROOT = Path(__file__).parent
source = json.loads((ROOT / "halo.frames.review.json").read_text(encoding="utf-8"))
frames = {item["id"]: item for item in source["frames"]}


def C(token, reading, roma, zh, pos, function=None, render=True):
    result = {"token": token, "reading": reading, "romaji": roma, "zhMeaning": zh, "posZh": pos,
              "render": render, "showJlpt": False, "reviewRequired": True}
    if function:
        result["functionZh"] = function
    return result


def set_frame(fid, translation, cards):
    frame = frames[fid]
    frame["caption"]["translationZh"] = translation
    frame["grammarCards"] = cards
    frame["caption"]["furigana"] = [{"base": c["token"], "reading": c["reading"], "romaji": c["romaji"]} for c in cards if c["render"]]
    frame["caption"]["romaji"] = " ".join(c["romaji"] for c in cards if c["render"])
    frame["analysisStatus"] = "assisted-linguistic-fill-needs-human-review"
    frame["reviewRequired"] = True


