for target, origin in (("l034", "l013"), ("l035", "l014"), ("l036", "l015"), ("l037", "l016"), ("l038", "l017"), ("l039", "l018"), ("l040", "l019"), ("l041", "l020"), ("l042", "l021")):
    frames[target]["grammarCards"] = copy.deepcopy(frames[origin]["grammarCards"])
    frames[target]["caption"]["furigana"] = copy.deepcopy(frames[origin]["caption"]["furigana"])
    frames[target]["caption"]["romaji"] = frames[origin]["caption"]["romaji"]
    frames[target]["caption"]["translationZh"] = frames[origin]["caption"]["translationZh"]
    frames[target]["analysisStatus"] = f"inherits-{origin}-assisted-linguistic-fill-needs-human-review"
    frames[target]["reviewRequired"] = True

source["reviewStatus"] = "assisted-linguistic-fill-needs-human-review"
source["assistedReviewSources"] = ["QQ Music qm/qmRoma/qmts", "authoritative dictionary/grammar web pass", "semantic chunking review"]
target = ROOT / "halo.frames.assisted.review.json"
target.write_text(json.dumps(source, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

lines = ["# HALO｜智能填充待审核", "", "已结合 QQ Music 中文轨、逐词时序与联网语法复核。请直接修改不满意的句译、词卡含义/功能或词性；确认后回复“核对完了”。", "", "重复继承：l034←l013、l035←l014、l036←l015、l037←l016、l038←l017、l039←l018、l040←l019、l041←l020、l042←l021。", ""]
for frame in source["frames"]:
    cap = frame["caption"]
    lines += [f"## {frame['id']} · {frame['startMs'] / 1000:.3f}s", "", f"日文：{cap['japanese']}", f"暂定中文：{cap['translationZh']}", "", "待核词卡："]
    cards = frame["grammarCards"]
    if not any(item["render"] for item in cards):
        lines.append("- 英语问候语：仅展示歌词，不渲染词卡、假名或罗马音。")
    else:
        for item in cards:
            if item["render"]:
                lines += [f"- `{item['token']}`｜{item['reading']}｜{item['romaji']}", f"  - 暂定：{item.get('functionZh', item['zhMeaning'])}", f"  - 词性：{item['posZh']}"]
    lines.append("")
(ROOT.parent / "deliverables" / "halo-assisted-review.md").write_text("\n".join(lines), encoding="utf-8")
print(target)
